class SMSKeywordRule(BaseModel):
    model_config = ConfigDict(extra="allow")
    id: Annotated[str, Field(
        description="Identifier of a keyword rule. An `sks_` id is one of Bird's defaults, which you can read but not change; an `skw_` id is a rule your workspace created.",
        examples=["skw_01krdgeqcxet5s7t44vh8rt9mg"],
        min_length=1,
        pattern="^(sks|skw)_[0-9a-hjkmnp-tv-z]{26}$",
    )]
    scope: Annotated[SMSKeywordRuleScope, Field(
        description="Whether the rule is one of Bird's defaults (`system`) or one your workspace created (`workspace`). A `workspace` rule takes precedence over Bird's default for the same country, so it is how you replace a reply without losing the keywords Bird ships.",
    )]
    operation: Annotated[Union[SMSKeywordOperation, str], Field(
        description="What Bird does when an inbound message matches the rule.\n\n- `stop` unsubscribes the sender from further messages.\n- `start` resubscribes them.\n- `help` replies with your support information.\n- `info` replies with your program information. It behaves exactly as `help` does and is\n  separate so a country whose INFO answer must differ from its HELP answer can carry both.\n  Where Bird ships no `info` rule for a country, INFO is one of that country's `help`\n  keywords and answers with the `help` reply.\n- `confirm` marks a double opt-in reply. It sends nothing today, so answer it from your own\n  handler.\n- `custom` replies with the text you configured and has no other effect.\n\nBird's built-in rules fix the operation for `stop`, `start` and `help`; you can change their\nreply but not what they do. The same holds for `info` in any country where Bird ships an\n`info` rule. This is an open enum. Accept unrecognized values.",
        union_mode="left_to_right",
    )]
    country: Annotated[Optional[str], Field(
        description="The country the rule applies in, as an ISO 3166-1 alpha-2 code. A rule for `NL` covers messages received on your Dutch numbers, and messages from a subscriber whose own number is Dutch whichever of your numbers they text. Rules for the country a message arrives in always outrank rules for the country its sender is in; within each, your rule wins over Bird's keywords for that country. `number` confines a rule to one number. Null means the rule applies worldwide, which is allowed for `custom` operations only.",
        examples=["NL"],
        max_length=2,
        min_length=2,
    )] = None
    language: Annotated[Optional[str], Field(
        description="The language this rule covers, in countries where Bird ships keywords in more than one. Canada has separate English and French rules, so a Canadian rule names which one it replaces and the other keeps Bird's reply. Null in countries with a single set.",
        examples=["fr"],
        min_length=2,
    )] = None
    number: Annotated[Optional[str], Field(
        description="Narrows the rule to one of your numbers in E.164 format, instead of every number you hold in the country. Null means it applies to all of them.",
        examples=[+18005551234],
        min_length=1,
    )] = None
    keywords: Annotated[List[str], Field(
        description="The keywords this rule adds. For one of Bird's defaults this is the full set Bird ships. For a rule you created it is only what you added on top. It never restates or removes Bird's keywords, so `effective_keywords` is what actually matches.",
    )]
    effective_keywords: Annotated[List[str], Field(
        description="Every keyword that matches this rule: Bird's keywords for the same operation, country and language, plus the ones you added. This is what an inbound message is compared against. Keywords Bird adds later join it without you changing anything.",
    )]
    reply: Annotated[Optional[str], Field(
        description="The message sent back when one of the keywords matches, except on a `confirm` rule, which never sends one. Null when the auto-reply is switched off, which `reply_disabled_at` distinguishes from a rule that has not been given one.",
        examples=["You have been unsubscribed and will receive no further messages."],
        min_length=1,
    )] = None
    reply_suffix: Annotated[Optional[str], Field(
        description="Text appended to your reply that you cannot change: the rates and opt-out wording carriers require on a help response. Your reply is sent in front of it, and both count against the length a single message allows. Null when the operation carries none.",
        examples=["Msg&data rates may apply. Reply STOP to unsubscribe."],
        min_length=1,
    )] = None
    reply_disabled_at: Annotated[Optional[str], Field(
        description="When the auto-reply for this rule was switched off, or null if it is on. Switching it off records that you send this reply from your own system, which is what Bird points to if a carrier asks why no reply went out.",
        examples=["2026-08-12T09:00:00Z"],
    )] = None
    mandatory: Annotated[bool, Field(
        description="Whether what this operation does is fixed. When true you can change the reply but not the behavior. An opt-out keyword always unsubscribes the sender, whichever rule matched it, because carriers and regulators require it.",
        examples=[True],
    )]
    created_at: Annotated[str, Field(
        description="When the rule was created.",
        examples=["2026-08-12T09:00:00Z"],
        min_length=1,
    )]
    updated_at: Annotated[str, Field(
        description="When the rule was last changed. On one of Bird's defaults this is when Bird last changed the keywords or the reply for that country.",
        examples=["2026-08-12T09:00:00Z"],
        min_length=1,
    )]


