class EventEmailMailboxMessageReceivedDataAuthentication(str, Enum):
    pass_ = "pass"
    fail = "fail"
    unknown = "unknown"


class EventEmailMailboxMessageReceivedData(BaseModel):
    model_config = ConfigDict(extra="allow")
    message_id: Annotated[str, Field(
        examples=["rem_01krdgeqcxet5s7t44vh8rt9mg"],
        min_length=1,
        pattern="^rem_[0-9a-hjkmnp-tv-z]{26}$",
    )]
    mailbox_id: Annotated[str, Field(
        examples=["mbx_01krdgeqcxet5s7t44vh8rt9mg"],
        min_length=1,
        pattern="^mbx_[0-9a-hjkmnp-tv-z]{26}$",
    )]
    thread_id: Annotated[str, Field(
        examples=["thr_01krdgeqcxet5s7t44vh8rt9mg"],
        min_length=1,
        pattern="^thr_[0-9a-hjkmnp-tv-z]{26}$",
    )]
    route_id: Annotated[Optional[str], Field(
        description="ID (ein_…) of the explicit inbound route that matched, or null when the message was delivered by the virtual exact-address route.",
        examples=["null"],
    )] = None
    from_: Annotated[str, Field(
        alias="from",
        description="Envelope-from address.",
        examples=["alice@example.com"],
        min_length=1,
    )]
    to: Annotated[List[str], Field(
        description="Recipient addresses the message was sent to.",
    )]
    subject: Annotated[Optional[str], Field(
        description="Subject line as received, or null when the message had no subject.",
        examples=["Re: Your quote"],
    )]
    extracted_text: Annotated[Optional[str], Field(
        description="Plain-text body with quoted history removed, capped at 64 KB. See `truncated_text` to check whether the value was truncated. Null when extraction produces no text.",
        examples=["Sounds good — can you send the invoice?"],
    )] = None
    truncated_text: Annotated[Optional[bool], Field(
        description="True when `extracted_text` was truncated to the 64 KB cap. Fetch the full text through the thread-member endpoint.",
    )] = None
    attachment_count: Annotated[int, Field(
        description="Number of attachments on the message. Attachment content remains available during the 30-day original-source retention window.",
        examples=[1],
        ge=0,
    )]
    authentication: Annotated[Optional[EventEmailMailboxMessageReceivedDataAuthentication], Field(
        description="Whether the sender of the received message was authenticated.\n\n- `pass`: the sender's identity was verified.\n- `fail`: it was checked and did not verify.\n- `unknown`: no verdict is available, so do not treat the sender\n  as verified.",
    )] = None
    spf_pass: Annotated[Optional[bool], Field(
        description="Whether SPF passed for the sender, or null when no verdict was computable.",
    )] = None
    dkim_pass: Annotated[Optional[bool], Field(
        description="Whether DKIM passed for the sender, or null when no verdict was computable.",
    )] = None
    dmarc_pass: Annotated[Optional[bool], Field(
        description="Whether DMARC passed for the sender, or null when no verdict was computable.",
    )] = None


